let _lang = detectLang();

function detectLang() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved && DICT[saved]) return saved;
  } catch { /* 私密模式等場景下 localStorage 不可用 */ }
  const nav = String(navigator.language || "").toLowerCase();
  if (nav.startsWith("zh")) return "zh";
  if (nav.startsWith("en")) return "en";
  if (nav.startsWith("es")) return "es";
  if (nav.startsWith("fr")) return "fr";
  if (nav.startsWith("ru")) return "ru";
  if (nav.startsWith("ja")) return "ja";
  if (nav.startsWith("de")) return "de";
  if (nav.startsWith("ko")) return "ko";
  if (nav.startsWith("ar")) return "ar";
  if (nav.startsWith("hi")) return "hi";
  if (nav.startsWith("vi")) return "vi";
  if (nav.startsWith("id")) return "id";
  if (nav.startsWith("pt")) return "pt";
  if (nav.startsWith("bn")) return "bn";
  if (nav.startsWith("ur")) return "ur";
  return "zh";
}

export function getLang() { return _lang; }

export function setLang(code) {
  if (!DICT[code] || code === _lang) return;
  _lang = code;
  try { localStorage.setItem(STORAGE_KEY, code); } catch { /* ignore */ }
  applyI18nDom();
  window.dispatchEvent(new CustomEvent("langchange", { detail: { lang: code } }));
}

// 取詞：缺 key 時 en → zh → key 自身
export function t(key, params) {
  const d = DICT[_lang] || DICT.zh;
  let s = d[key];
  if (s == null) s = DICT.en[key];
  if (s == null) s = DICT.zh[key];
  if (s == null) return key;
  if (params) {
    for (const [k, v] of Object.entries(params)) s = s.split(`{${k}}`).join(String(v));
  }
  return s;
}

// 把靜態 HTML 中的 data-i18n* 屬性翻譯一遍
export function applyI18nDom(root = document) {
  document.documentElement.lang = _lang;
  // 阿拉伯語等 RTL 語言要一併設定 dir，整站版面才會鏡像（配合 styles.css 的邏輯屬性寫法）
  const meta = LANGS.find((l) => l.code === _lang);
  if (meta && meta.dir) document.documentElement.dir = meta.dir;
  else document.documentElement.removeAttribute("dir");
  root.querySelectorAll("[data-i18n]").forEach((n) => { n.textContent = t(n.getAttribute("data-i18n")); });
  root.querySelectorAll("[data-i18n-html]").forEach((n) => { n.innerHTML = t(n.getAttribute("data-i18n-html")); });
  root.querySelectorAll("[data-i18n-ph]").forEach((n) => { n.setAttribute("placeholder", t(n.getAttribute("data-i18n-ph"))); });
  root.querySelectorAll("[data-i18n-title]").forEach((n) => { n.setAttribute("title", t(n.getAttribute("data-i18n-title"))); });
  root.querySelectorAll("[data-i18n-aria]").forEach((n) => { n.setAttribute("aria-label", t(n.getAttribute("data-i18n-aria"))); });
}

// 首次進入時初始化（設定 <html lang> 並翻譯靜態文字）
export function initI18n() {
  applyI18nDom();
}
